	private CharBuffer iriChars(long id, int depth) {
		Frame frame = frame(depth);
		ByteBuffer value = read(id, frame);
		if (value.get() != 0) {
			throw new SailException("Datatype identity is not an IRI");
		}
		long namespace = Varint.readUnsigned(value);
		int localOffset = value.position(), localLength = value.remaining();
		Frame namespaceFrame = frame(depth + 1);
		ByteBuffer namespaceBytes = read(namespace, namespaceFrame);
		int namespaceLength = namespaceBytes.remaining() - 1;
		frame.chars = capacity(frame.chars, namespaceLength + localLength + 1);
		frame.chars.clear();
		decodeInto(namespaceBytes, 1, namespaceLength, frame, frame.chars);
		decodeInto(value, localOffset, localLength, frame, frame.chars);
		return frame.chars.flip();
	}

	private void triple(long id, Frame frame) {
		TripleIndex index = store.countTripleTermCspoIndex();
		frame.keyBytes.clear();
		index.getMinKey(frame.keyBytes, -1, -1, -1, id);
		frame.key.mv_data(frame.keyBytes.flip());
		if (frame.tripleCursor == 0) {
			frame.tripleCursor = cursor(index.getDB(true));
		}
		int rc = mdb_cursor_get(frame.tripleCursor, frame.key, frame.data, MDB_SET_RANGE);
		if (rc == MDB_NOTFOUND) {
			throw new SailException("Triple term identity " + id + " is unavailable in the frozen count dictionary");
		}
		check(rc);
		ByteBuffer key = frame.returnedKeyBytes();
		if (Varint.readUnsigned(key) != id) {
			throw new SailException("Triple term identity " + id + " is unavailable in the frozen count dictionary");
		}
		frame.subject = Varint.readUnsigned(key);
		frame.predicate = Varint.readUnsigned(key);
		frame.object = Varint.readUnsigned(key);
	}

	private void literalIdentity(long id, Frame frame) {
		frame.direction = 0;
		frame.datatype = 0;
		frame.languageChars.clear().limit(0);
		if (ValueIds.isInlined(id)) {
			if (ValueIds.getIdType(id) == ValueIds.T_SHORTSTRING) {
				Values.unpackStringUtf8(id, frame.keyBytes);
				frame.labelChars.clear();
				decodeInto(frame.keyBytes, 0, frame.keyBytes.remaining(), frame, frame.labelChars);
				frame.labelChars.flip();
			} else {
				String label = Values.unpackLabel(id);
				frame.labelChars = capacity(frame.labelChars, label.length());
				frame.labelChars.clear().put(label).flip();
			}
			frame.datatypeIri = Values.unpackDatatype(id).getIri().stringValue();
			return;
		}
		ByteBuffer value = read(id, frame);
		int length = literalHeader(value, frame);
		if (length > 0) {
			frame.languageChars = capacity(frame.languageChars, length + 1);
			frame.languageChars.clear();
			decodeInto(value, value.position(), length, frame, frame.languageChars);
			frame.languageChars.flip();
		}
		int labelLength = value.remaining() - length;
		frame.labelOffset = value.position() + length;
		frame.labelLength = labelLength;
		frame.labelChars = capacity(frame.labelChars, labelLength + 1);
		frame.labelChars.clear();
		decodeInto(value, value.position() + length, labelLength, frame, frame.labelChars);
		frame.labelChars.flip();
		if (length > 0) {
			frame.datatypeIri = (frame.direction == 1 || frame.direction == 2
					? CoreDatatype.RDF.DIRLANGSTRING
					: CoreDatatype.RDF.LANGSTRING).getIri().stringValue();
		} else {
			frame.datatypeIri = frame.datatype == 0 ? CoreDatatype.XSD.STRING.getIri().stringValue()
					: null;
		}
		if (frame.direction != 1 && frame.direction != 2) {
			frame.direction = 0;
		}
	}

	private static int literalHeader(ByteBuffer value, Frame frame) {
		value.get();
		frame.datatype = Varint.readUnsigned(value);
		frame.payloadOffset = value.position();
		int directionAndLength = value.get() & 0xFF;
		frame.direction = directionAndLength >>> 6;
		if (frame.direction == 3) {
			frame.direction = directionAndLength & 0x3F;
			return (int) Varint.readUnsigned(value);
		}
		return directionAndLength & 0x3F;
	}

	/** The fixed prefix includes every valid header; unrelated literal payloads need no copying or decoding. */
	private static boolean hasLanguage(MDBVal data, Frame frame) {
		int bytes = (int) Math.min(data.mv_size(), MAX_LITERAL_HEADER_BYTES);
		frame.keyBytes.clear().limit(bytes);
		memCopy(memGetAddress(data.address() + MDBVal.MV_DATA), memAddress(frame.keyBytes), bytes);
		return literalHeader(frame.keyBytes, frame) > 0;
	}

	private void literal(long id, Frame frame, int depth) {
		literalIdentity(id, frame);
		frame.label = frame.labelChars.toString();
		frame.language = frame.languageChars.hasRemaining() ? frame.languageChars.toString() : null;
		if (frame.datatypeIri == null) {
			frame.datatypeIri = iri(frame.datatype, depth + 1);
		}
	}

	static int mix(int hash, int value) {
		return 31 * hash + value;
	}

	static int cacheSlot(long id, int mask) {
		long mixed = (id ^ id >>> 33) * 0xff51afd7ed558ccdL;
		mixed = (mixed ^ mixed >>> 33) * 0xc4ceb9fe1a85ec53L;
		return (int) (mixed ^ mixed >>> 33) & mask;
	}

	private static int lexicalHash(CharSequence value) {
		int hash = 0;
		for (int i = 0; i < value.length(); i++) {
			hash = mix(hash, value.charAt(i));
		}
		return hash;
	}

	private static boolean lexicalEquals(CharSequence left, CharSequence right) {
		if (left.length() != right.length()) {
			return false;
		}
		for (int i = 0; i < left.length(); i++) {
			if (left.charAt(i) != right.charAt(i)) {
				return false;
			}
		}
		return true;
	}

	private static boolean foldedEquals(CharSequence left, CharSequence right) {
		if (left.length() != right.length()) {
			return false;
		}
		for (int i = 0; i < left.length();) {
			int l = Character.codePointAt(left, i), r = Character.codePointAt(right, i);
			if (l != r) {
				int upperLeft = Character.toUpperCase(l), upperRight = Character.toUpperCase(r);
				if (upperLeft != upperRight
						&& Character.toLowerCase(upperLeft) != Character.toLowerCase(upperRight)) {
					return false;
				}
			}
			i += Character.charCount(l);
		}
		return true;
	}

	static int languageHash(CharSequence language) {
		if (language == null) {
			return 0;
		}
		int hash = 0;
		for (int i = 0; i < language.length();) {
			int cp = Character.codePointAt(language, i);
			i += Character.charCount(cp);
			hash = mix(hash, Character.toLowerCase(Character.toUpperCase(cp)));
		}
		return hash;
	}

	private boolean datatypeEquals(Frame literal, String lexical, int depth) {
		return literal.datatypeIri != null ? literal.datatypeIri.equals(lexical)
				: lexicalEquals(iriChars(literal.datatype, depth), lexical);
	}

	private boolean datatypeMatches(Frame literal, LmdbCountValue datatype, int depth) {
		if (literal.datatypeIri == null) {
			return matches(literal.datatype, datatype, depth);
		}
		datatype.checkRevision();
		return datatype.origin == null ? literal.datatypeIri.equals(datatype.lexical)
				: lexicalEquals(datatype.origin.reader().iriChars(datatype.id, depth), literal.datatypeIri);
	}

	private boolean sameDatatype(Frame left, LmdbCountDictionary other, Frame right, int depth) {
		if (left.datatypeIri != null) {
			return other.datatypeEquals(right, left.datatypeIri, depth);
		}
		if (right.datatypeIri != null) {
			return datatypeEquals(left, right.datatypeIri, depth);
		}
		return lexicalEquals(iriChars(left.datatype, depth), other.iriChars(right.datatype, depth + 1));
	}

	static int literalHash(String label, String datatype, String language, int direction) {
		return mix(mix(mix(mix(ValueIds.T_LITERAL, label.hashCode()), datatype.hashCode()), languageHash(language)),
				direction);
	}

